#include "core/catalog/wiki_data.hpp"

#include <cstddef>

#include "core/guide/stations.hpp"
#include "core/util/json.hpp"

// The build's data file as bytes (wiki_data_blob.cpp, generated by CMake).
extern const unsigned char kMarigoldWikiData[];
extern const std::size_t kMarigoldWikiDataSize;

namespace marigold::catalog::wiki {

const std::vector<std::string>* Data::callsignsOf(std::string_view marketName) const {
  auto it = callsigns.find(markets::nameKey(marketName));
  return it == callsigns.end() || it->second.empty() ? nullptr : &it->second;
}

std::string toJson(const Data& data) {
  json::Value v = json::Value::object();
  v.set("version", 1);
  v.set("made", data.made);
  json::Value list = json::Value::array();
  for (const markets::Market& m : data.markets) {
    json::Value item = json::Value::object();
    item.set("name", m.name);
    if (m.templateName) item.set("template", *m.templateName);
    if (const std::vector<std::string>* calls = data.callsignsOf(m.name)) {
      json::Value c = json::Value::array();
      for (const std::string& s : *calls) c.push(s);
      item.set("callsigns", c);
    }
    list.push(item);
  }
  v.set("markets", list);
  // The station directory in its own saved form.
  if (auto stations = json::parse(guide::stations::toJson(data.stations))) v.set("stations", *stations);
  return json::write(v);
}

std::optional<Data> fromJson(std::string_view text) {
  auto doc = json::parse(text);
  if (!doc || !doc->isObject()) return std::nullopt;
  Data data;
  if ((*doc)["made"].isString()) data.made = (*doc)["made"].asString();
  for (const json::Value& item : (*doc)["markets"].items()) {
    if (!item["name"].isString() || item["name"].asString().empty()) continue;
    markets::Market m;
    m.name = item["name"].asString();
    if (item["template"].isString()) m.templateName = item["template"].asString();
    std::vector<std::string> calls;
    for (const json::Value& c : item["callsigns"].items()) {
      if (c.isString()) calls.push_back(c.asString());
    }
    if (!calls.empty()) data.callsigns[markets::nameKey(m.name)] = std::move(calls);
    data.markets.push_back(std::move(m));
  }
  const json::Value& stations = (*doc)["stations"];
  if (!stations.isNull()) {
    if (auto list = guide::stations::fromJson(json::write(stations))) data.stations = std::move(*list);
  }
  return data;
}

const Data& builtIn() {
  static const Data kData = [] {
    if (kMarigoldWikiDataSize == 0) return Data{};
    std::string_view text(reinterpret_cast<const char*>(kMarigoldWikiData), kMarigoldWikiDataSize);
    return fromJson(text).value_or(Data{});
  }();
  return kData;
}

}  // namespace marigold::catalog::wiki
